const projects=[
{id:'prism',name:'Prism Network',symbol:'◈',category:'Testnet',chain:'Ethereum',color:'#bc9aff',glow:'#693dc370',desc:'A new perspective on scalable, connected blockchains.',featured:true,tasks:['Read the project introduction','Explore the testnet guide','Try the demo application','Record your experience']},
{id:'orbit',name:'Orbit Protocol',symbol:'◎',category:'DeFi',chain:'Arbitrum',color:'#73d8f3',glow:'#237a9960',desc:'Discover a more open universe of decentralized finance.',featured:true,tasks:['Read the protocol overview','Review the risk documentation','Explore the interface','Add research notes']},
{id:'nova',name:'Nova Worlds',symbol:'✧',category:'Gaming',chain:'Polygon',color:'#e8b880',glow:'#a66b3160',desc:'Play, explore, and collect in a world built by its community.',featured:true,tasks:['Explore the game concept','Read community guidelines','Preview the world','Save your discoveries']},
{id:'echo',name:'Echo Intelligence',symbol:'✳',category:'AI',chain:'Base',color:'#7de3bf',glow:'#286b6260',desc:'An open ecosystem at the intersection of AI and Web3.',tasks:['Read the research brief','Explore the product overview','Review the roadmap','Track your research']},
{id:'aether',name:'Aether Layer',symbol:'△',category:'Infra',chain:'Ethereum',color:'#9bafff',glow:'#3e4e9960',desc:'The building blocks for the next generation of applications.',tasks:['Read the architecture guide','Explore developer resources','Review the ecosystem','Save your research']},
{id:'canvas',name:'Canvas Collective',symbol:'❖',category:'NFT',chain:'Solana',color:'#f0a5d2',glow:'#8b3e7460',desc:'A digital home for art, collectors, and creative communities.',tasks:['Discover the collection concept','Read creator guidelines','Explore the gallery','Save your favorite discoveries']}
];
const nav=[['home','⌂','Overview'],['explore','⌕','Explore'],['tasks','☑','My Tasks'],['collection','◇','Collection'],['profile','♙','Profile']];
let state;try{state=JSON.parse(localStorage.getItem('airdrop-museum-v1'))||{}}catch{state={}}state.saved=Array.isArray(state.saved)?state.saved:[];state.done=state.done&&typeof state.done==='object'?state.done:{};
let page='home',category='All',query='',sort='featured';const app=document.querySelector('#app');
const persist=()=>{try{localStorage.setItem('airdrop-museum-v1',JSON.stringify(state))}catch{toast('Penyimpanan browser tidak tersedia. Progres hanya untuk sesi ini.')}};
function toast(s){const el=document.querySelector('#toast');el.textContent=s;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),3000)}
function done(p){return p.tasks.filter((_,i)=>state.done[p.id+':'+i]===true).length}function total(){return projects.reduce((n,p)=>n+done(p),0)}
function navigate(id){page=id;query='';category='All';render();window.scrollTo({top:0,behavior:'smooth'})}
function renderNav(){for(const id of ['desktop-nav','mobile-nav'])document.getElementById(id).innerHTML=nav.map(([key,icon,label])=>`<button data-nav="${key}" class="${page===key?'active':''}" ${page===key?'aria-current="page"':''}><i aria-hidden="true">${icon}</i>${label}</button>`).join('');document.querySelector('#page-label').textContent=nav.find(x=>x[0]===page)[2]}
const intro=(title,desc)=>`<div class="intro"><div><span class="eyeline">DISCOVER · COLLECT · GROW</span><h1>${title}</h1><p>${desc}</p></div><span class="date">Your personal discovery space ↗</span></div>`;
const stats=()=>`<div class="stats">${[['◈',projects.length,'Demo projects'],['◇',state.saved.length,'In your collection'],['✓',total(),'Tasks completed'],['✧',total()*50,'Local XP']].map(([i,n,l])=>`<div class="stat"><span class="stat-icon">${i}</span><div><b>${n.toLocaleString()}</b><small>${l}</small></div></div>`).join('')}</div>`;
function card(p){const progress=done(p)/p.tasks.length*100;return `<article class="card"><div class="card-art" style="--color:${p.color};--glow:${p.glow}"><span class="tag">${p.featured?'✦ Featured':'✧ Discover'}</span><button class="save ${state.saved.includes(p.id)?'saved':''}" data-save="${p.id}" aria-label="${state.saved.includes(p.id)?'Hapus':'Simpan'} ${p.name}" aria-pressed="${state.saved.includes(p.id)}">${state.saved.includes(p.id)?'◆':'◇'}</button><span class="project-symbol">${p.symbol}</span></div><div class="card-body"><div class="card-heading"><h3>${p.name}</h3><small>Demo</small></div><p>${p.desc}</p><div class="tags"><span class="tag-inline">${p.category}</span><span class="tag-inline">${p.chain}</span></div><div class="card-bottom"><span>${done(p)}/${p.tasks.length} tasks completed</span><button class="text-btn" data-open="${p.id}">Explore ↗</button></div><div class="progress" aria-label="${progress}% selesai"><span style="width:${progress}%"></span></div></div></article>`}
function catalog(){return `<div class="section-title"><h2>${page==='collection'?'Your curated collection':'Discover the collection'} <span style="color:#73658f">✦</span></h2><small id="count"></small></div><div class="toolbar"><label class="search"><span aria-hidden="true">⌕</span><input id="search" type="search" aria-label="Cari proyek" placeholder="Search projects, chains, or categories..."></label><select id="sort" aria-label="Urutkan proyek"><option value="featured">Featured first</option><option value="name">Name A–Z</option><option value="progress">My progress</option></select></div><div class="filters">${['All','Testnet','DeFi','Gaming','AI','Infra','NFT'].map(c=>`<button class="chip ${category===c?'active':''}" data-category="${c}" aria-pressed="${category===c}">${c==='All'?'✦ All projects':c}</button>`).join('')}</div><div class="grid" id="project-grid"></div>`}
function updateGrid(){let list=projects.filter(p=>(page!=='collection'||state.saved.includes(p.id))&&(category==='All'||p.category===category)&&[p.name,p.chain,p.category].join(' ').toLowerCase().includes(query.toLowerCase()));list.sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):sort==='progress'?done(b)-done(a):Number(!!b.featured)-Number(!!a.featured));document.querySelector('#project-grid').innerHTML=list.length?list.map(card).join(''):'<div class="empty">No projects found.<br>Try another filter or save a project to your collection.</div>';document.querySelector('#count').textContent=list.length+' projects';document.querySelectorAll('[data-category]').forEach(x=>{x.classList.toggle('active',x.dataset.category===category);x.setAttribute('aria-pressed',String(x.dataset.category===category))})}
function render(){renderNav();if(['home','explore','collection'].includes(page)){app.innerHTML=intro(page==='home'?'A little early. A lot of possibility.':page==='explore'?'Find your next discovery.':'Your collection. Your journey.',page==='home'?'Welcome to Airdrop Museum. Your next discovery starts here.':page==='explore'?'Explore projects by ecosystem, interest, and curiosity.':'Keep the projects worth coming back to, all in one place.')+(page==='home'?`<section class="hero"><div class="hero-copy"><span class="pill">THE EARLY EXPLORER’S CLUB</span><h2>Discover potential.<br><em>Collect possibilities.</em></h2><p>A curated space for your airdrop journey. Explore new ecosystems, track tasks, and stay one step ahead.</p><button class="primary" data-nav="explore">Explore the museum <span style="margin-left:12px">↗</span></button></div><div class="hero-art" aria-hidden="true"><div class="ring"></div><div class="ring two"></div><div class="orb"></div><span class="art-label">THE NEXT DISCOVERY</span></div></section>`:'')+stats()+catalog()+`<section class="bottom-banner"><div><h3>Small steps. New discoveries.</h3><p>Turn your research into a collection worth keeping.</p></div><button class="secondary" data-nav="tasks">My tasks ↗</button></section>`;updateGrid();document.querySelector('#sort').value=sort;document.querySelector('#search').addEventListener('input',e=>{query=e.target.value;updateGrid()});document.querySelector('#sort').addEventListener('change',e=>{sort=e.target.value;updateGrid()})}
else if(page==='tasks'){app.innerHTML=intro('One step closer.','Your personal checklist. Completion is self-reported, not verified on-chain.')+stats()+projects.map(p=>`<section class="panel"><div class="section-title"><h3>${p.symbol} ${p.name}</h3><small>${done(p)}/${p.tasks.length} complete</small></div>${taskList(p)}</section>`).join('')}
else{app.innerHTML=intro('Make curiosity your superpower.','Your museum pass and local exploration history.')+`<section class="panel profile-card"><div class="avatar profile-avatar" style="display:grid;place-items:center">X</div><span class="eyeline">MUSEUM EXPLORER</span><h2>XIRRAEN</h2><p>Local profile · Level ${Math.floor(total()/4)+1} · ${total()*50} XP</p></section>`+stats()+`<section class="panel"><h3>Your explorer badges</h3><div class="badge-grid">${[['◈','First discovery',state.saved.length>0],['✓','First steps',total()>0],['✦','Task curator',total()>=12],['◇','Collector',state.saved.length>=3]].map(([s,n,earned])=>`<div class="badge"><strong style="opacity:${earned?1:.25}">${s}</strong>${n}<br><small>${earned?'Unlocked':'Locked'}</small></div>`).join('')}</div></section><section class="panel"><h3>Wallet & rewards</h3><p>No wallet is connected. This version tracks research locally and does not sign transactions or distribute rewards.</p><div class="notice">All six projects are fictional demo content. XP is local, has no monetary value, and does not establish airdrop eligibility.</div></section><section class="panel"><h3>Your data</h3><p>Bookmarks and task progress are saved in this browser. Export a backup to keep your collection.</p><button class="secondary" id="export">Export my progress ↓</button></section>`}}
function taskList(p){return p.tasks.map((t,i)=>`<button class="task ${state.done[p.id+':'+i]?'done':''}" data-task="${p.id}:${i}" aria-pressed="${!!state.done[p.id+':'+i]}"><span class="check">${state.done[p.id+':'+i]?'✓':''}</span><span>${t}</span><small>+50 XP</small></button>`).join('')}
let openId=null;function showDetail(id){const p=projects.find(p=>p.id===id);if(!p)return;openId=id;document.querySelector('#detail-content').innerHTML=`<div class="detail-top" style="--glow:${p.glow}"><button class="close" id="close" aria-label="Tutup detail">×</button><span class="project-symbol" style="--color:${p.color};--glow:${p.glow}">${p.symbol}</span></div><div class="detail-body"><div class="section-title"><h2>${p.name}</h2><button class="secondary" data-save="${p.id}">${state.saved.includes(p.id)?'◆ Saved':'◇ Save'}</button></div><div class="tags"><span class="tag-inline">${p.category}</span><span class="tag-inline">${p.chain}</span></div><p>${p.desc}</p><div class="notice">Fictional demo project. No live campaign, financial estimate, or eligibility claim. These research tasks are self-reported.</div><div class="section-title"><h3>Research checklist</h3><small>${done(p)} / ${p.tasks.length}</small></div>${taskList(p)}<div class="progress"><span style="width:${done(p)/p.tasks.length*100}%"></span></div></div>`;if(!document.querySelector('#detail').open)document.querySelector('#detail').showModal()}
document.addEventListener('click',e=>{const n=e.target.closest('[data-nav]');if(n){navigate(n.dataset.nav);return}const c=e.target.closest('[data-category]');if(c){category=c.dataset.category;updateGrid();return}const s=e.target.closest('[data-save]');if(s){const id=s.dataset.save;state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];persist();if(document.querySelector('#detail').open){showDetail(id);render()}else render();return}const o=e.target.closest('[data-open]');if(o){showDetail(o.dataset.open);return}const t=e.target.closest('[data-task]');if(t){state.done[t.dataset.task]=!state.done[t.dataset.task];persist();render();if(document.querySelector('#detail').open)showDetail(openId);return}if(e.target.closest('#close'))document.querySelector('#detail').close();if(e.target.closest('#export')){const blob=new Blob([JSON.stringify({version:1,exportedAt:new Date().toISOString(),...state},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='airdrop-museum-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Progress exported.')}});document.querySelector('#profile-top').onclick=()=>navigate('profile');document.querySelector('#detail').addEventListener('click',e=>{if(e.target===e.currentTarget)e.currentTarget.close()});render();
